// This file is part of the uutils coreutils package.
//
// For the full copyright and license information, please view the LICENSE
// file that was distributed with this source code.

// spell-checker:ignore (ToDO) fname, algo
use clap::{crate_version, value_parser, Arg, ArgAction, Command};
use std::ffi::OsStr;
use std::fs::File;
use std::io::{self, stdin, stdout, BufReader, Read, Write};
use std::iter;
use std::path::Path;
use uucore::checksum::{
    calculate_blake2b_length, detect_algo, digest_reader, perform_checksum_validation,
    ChecksumError, ChecksumRecord, HashAlgorithm, ALGORITHM_OPTIONS_BLAKE2B, ALGORITHM_OPTIONS_BSD,
    ALGORITHM_OPTIONS_CRC, ALGORITHM_OPTIONS_SYSV, SUPPORTED_ALGORITHMS,
};
use uucore::{
    encoding,
    error::{FromIo, UResult, USimpleError},
    format_usage, help_about, help_section, help_usage, show,
    sum::{div_ceil, Digest},
};

const USAGE: &str = help_usage!("cksum.md");
const ABOUT: &str = help_about!("cksum.md");
const AFTER_HELP: &str = help_section!("after help", "cksum.md");

#[derive(Debug, PartialEq)]
enum OutputFormat {
    Hexadecimal,
    Raw,
    Base64,
}

struct Options {
    algorithm: HashAlgorithm,
    digest: Box<dyn Digest + 'static>,
    tag: bool, // will cover the --untagged option
    output_format: OutputFormat,
    asterisk: bool, // if we display an asterisk or not (--binary/--text)
}

impl Options {
    #[allow(clippy::cognitive_complexity)]
    fn write_digest(&self, algorithm: &HashAlgorithm, record: &ChecksumRecord) -> UResult<()> {
        let sum = match self.output_format {
            OutputFormat::Raw => {
                let bytes = match algorithm.name {
                    ALGORITHM_OPTIONS_CRC => record
                        .columns
                        .label
                        .digest_text
                        .parse::<u32>()
                        .unwrap()
                        .to_be_bytes()
                        .to_vec(),
                    ALGORITHM_OPTIONS_SYSV | ALGORITHM_OPTIONS_BSD => record
                        .columns
                        .label
                        .digest_text
                        .parse::<u16>()
                        .unwrap()
                        .to_be_bytes()
                        .to_vec(),
                    _ => hex::decode(&record.columns.label.digest_text).unwrap(),
                };
                // Cannot handle multiple files anyway, output immediately.
                stdout().write_all(&bytes)?;
                return Ok(());
            }
            OutputFormat::Hexadecimal => record.columns.label.digest_text.clone(),
            OutputFormat::Base64 => match algorithm.name {
                ALGORITHM_OPTIONS_CRC | ALGORITHM_OPTIONS_SYSV | ALGORITHM_OPTIONS_BSD => {
                    record.columns.label.digest_text.clone()
                }
                _ => encoding::encode(
                    encoding::Format::Base64,
                    &hex::decode(&record.columns.label.digest_text).unwrap(),
                )
                .unwrap(),
            },
        };
        let not_file = record.stdin_input;
        let filename = &record.filename;
        let sz = record.columns.file_bytes;
        let bsd_width = 5;
        let blocks = div_ceil(sz, algorithm.bits);
        let asterisk = record.columns.label.asterisk;
        let ending = record.columns.label.line_ending;

        match (algorithm.name, not_file) {
            (ALGORITHM_OPTIONS_SYSV, true) => {
                print!("{} {}{}", sum.parse::<u16>().unwrap(), blocks, ending)
            }
            (ALGORITHM_OPTIONS_SYSV, false) => print!(
                "{} {} {}{}",
                sum.parse::<u16>().unwrap(),
                blocks,
                filename.display(),
                ending
            ),
            (ALGORITHM_OPTIONS_BSD, true) => print!(
                "{:0bsd_width$} {:bsd_width$}{}",
                sum.parse::<u16>().unwrap(),
                blocks,
                ending
            ),
            (ALGORITHM_OPTIONS_BSD, false) => print!(
                "{:0bsd_width$} {:bsd_width$} {}{}",
                sum.parse::<u16>().unwrap(),
                blocks,
                filename.display(),
                ending
            ),
            (ALGORITHM_OPTIONS_CRC, true) => print!("{sum} {sz}{ending}"),
            (ALGORITHM_OPTIONS_CRC, false) => {
                print!("{sum} {sz} {}{ending}", filename.display())
            }
            (ALGORITHM_OPTIONS_BLAKE2B, _) if self.tag => {
                if algorithm.bits == 512 {
                    print!("BLAKE2b ({}) = {sum}{ending}", filename.display());
                } else {
                    // Multiply by 8 here, as we want to print the length in bits.
                    print!(
                        "BLAKE2b-{} ({}) = {sum}{ending}",
                        algorithm.bits * 8,
                        filename.display()
                    );
                }
            }
            _ => {
                if self.tag {
                    print!(
                        "{} ({}) = {sum}{ending}",
                        algorithm.name.to_ascii_uppercase(),
                        filename.display()
                    );
                } else {
                    let prefix = if asterisk { "*" } else { " " };
                    print!("{sum} {prefix}{}{ending}", filename.display());
                }
            }
        }

        Ok(())
    }
}

/// Calculate checksum
///
/// # Arguments
///
/// * `options` - CLI options for the assigning checksum algorithm
/// * `files` - A iterator of OsStr which is a bunch of files that are using for calculating checksum
#[allow(clippy::cognitive_complexity)]
fn cksum<'a, I>(mut options: Options, files: I) -> UResult<()>
where
    I: Iterator<Item = &'a OsStr>,
{
    let files: Vec<_> = files.collect();
    if options.output_format == OutputFormat::Raw && files.len() > 1 {
        return Err(Box::new(ChecksumError::RawMultipleFiles));
    }

    for filename in files {
        let filename = Path::new(filename);
        let stdin_buf;
        let file_buf;
        let not_file = filename == OsStr::new("-");

        // Handle the file input
        let mut file = BufReader::new(if not_file {
            stdin_buf = stdin();
            Box::new(stdin_buf) as Box<dyn Read>
        } else if filename.is_dir() {
            Box::new(BufReader::new(io::empty())) as Box<dyn Read>
        } else {
            file_buf = match File::open(filename) {
                Ok(file) => file,
                Err(err) => {
                    show!(err.map_err_context(|| filename.to_string_lossy().to_string()));
                    continue;
                }
            };
            Box::new(file_buf) as Box<dyn Read>
        });

        if filename.is_dir() {
            show!(USimpleError::new(
                1,
                format!("{}: Is a directory", filename.display())
            ));
            continue;
        }

        let (sum_hex, sz) = digest_reader(
            &mut options.digest,
            &mut file,
            false,
            options.algorithm.bits,
        )
        .map_err_context(|| "failed to read input".to_string())?;

        let record = ChecksumRecord::new(
            sz,
            sum_hex,
            options.asterisk,
            not_file,
            filename.to_path_buf(),
        );
        options.write_digest(&options.algorithm, &record)?;
    }

    Ok(())
}

mod options {
    pub const ALGORITHM: &str = "algorithm";
    pub const FILE: &str = "file";

